      "raw_content": "카페홈\n좌담회알바좌담회카페\n검색\n메뉴\n새로운 좌담/설문\n앱 열기\n11/27~12/2) 만20~29세 남성) 주류 맛테스트 설문+좌담회\n본문 기타 기능\n좌담회알바좌담회카페\n카페매니저\n채팅\n작성일\n2026.11.06. 10:16\n조회 61\n구독\n11/27~12/2) 만20~29세 남성) 주류 맛테스트 설문+좌담회\n11/27~12/2) 만20~49세 남/여) 주류 맛테스트 설문+좌담회\n1.대상\n-만20~49세 남/여\n-최근 1개월내에 국산 맥주를 마트,편의점,슈퍼 등에서 구매하여 드신 분\n-최근 3개월 내에 과일맛 맥주/하이볼/사와/RTD주류를 마트,편의점,슈퍼 등에서 구매하여 드신 분\n-음식 알러지 없고 임신/수유/당뇨/기타질병 아닌(없는) 분\n-1시간반 동안 맥주 500ml 이상 시음 가능한 분\n-12/1~12/2 2시,6시반 신청자는 1시간30분 설문 참여 후 좌담회 대상자로 선발시 남아서 좌담회(1시간40분)까지 참여 가능한 분\n2.일정 중 하루 한타임만 가능\n-설문 소요시간 : 1시간30분 / 추가 좌담회 소요시간: 1시간40분\n11/27(금) 오후 2시 / 4시 / 6시30분 / 8시30분\n11/30(월) 오후 2시 / 4시 / 6시30분 / 8시30분\n12/1 (화) 오후 2시(좌담회 가능한분만) / 4시 / 6시30분(좌담회 가능한분만) / 8시30분\n12/2 (수) 오후 2시 (좌담회 가능한분만) / 4시 / 6시30분(좌담회 가능한분만) / 8시30분\n2호선 충정로역 부근\n3.참석 사례비\n-설문 참여비: 3만5천원\n-추가 좌담회 참여비: 3만5천원 (특정 날짜,시간대 참석자만 참여)\n*설문+좌담회 모두 참여자는 총 7만원 지급\n4.신청방법:\n아래 신청 버튼을 클릭하면 대상자 선정을 위한 신청페이지가 나옵니다.\n접속하여 설문응답 진행해주세요.\n설문응답 첫 문항 소개자명에 [_____]를 필수로 기입해주세요.\n소개자 이름에 소개자명 송난주 반드시!!!! 누락없이 작성 바랍니다.\nhttps://tally.so/r/OQaNBY\n소개자 이름에 소개자명 송난주 반드시!!!! 누락없이 작성 바랍니다.\n좋아요\n0\n송파구에서 핫한 진짜 동네 이야기\n댓글\n1\n클린봇 이 악성 댓글을 감지합니다.\n댓글 알림 설정\n큰돌찬\n신입회원\nNew\n감사합니다\n2026.11.06. 14:33 답글쓰기\n옵션\n좋아요\n댓글을 남겨보세요\n전체글\n11/27~12/2) 만20~29세 여성) 주류 맛테스트 설문+좌담회\n좌담회알바좌담회카페\n26.11.06.\n댓글\n1\n11/27~12/2) 만20~29세 남성) 주류 맛테스트 설문+좌담회\n좌담회알바좌담회카페\n26.11.06.\n댓글\n1\n만나이 19~45세 여성 (2007~1980년생) 간식 맛 테스트 갱조사\n좌담회알바좌담회카페\n26.11.06.\n댓글\n1\n11/24~25) 1시간 40만) 20세 이상 ~ 남성) 푸드 크리에이터 온라인 화상 인터뷰\n좌담회알바좌담회카페\n26.11.06.\n댓글\n1\n새로운 좌담/설문\n 게시판\n의 글을 많이 보셨네요. 👀\n구독하고 관심글을 빠르게 확인하세요!\n게시판 구독하기\n목록으로\n좋아요\n0\n댓글\n1\n새로운 댓글\n공유하기\n새 글, 새 댓글을 놓치지 않게 카페앱으로 이용해보세요!\n앱으로 보기\n앱 설치하기\n네이버 메인에 추가\n맨위로\n로그아웃전체서비스PC버전\n이용약관\n개인정보처리방침\n카페 고객센터\n카페 공지사항\n오류신고\n© NAVER Corp.대표번호 : 1588-3820",
